CREATE TABLE IF NOT EXISTS service_config_jobs (
 id VARCHAR(36) PRIMARY KEY, session_id VARCHAR(64) NOT NULL, created_by VARCHAR(255) NOT NULL, operation VARCHAR(16) NOT NULL, status VARCHAR(24) NOT NULL, restart_requested BOOLEAN NOT NULL DEFAULT FALSE, total_nodes INT NOT NULL DEFAULT 0, completed_nodes INT NOT NULL DEFAULT 0, success_nodes INT NOT NULL DEFAULT 0, failed_nodes INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, started_at DATETIME NULL, finished_at DATETIME NULL, INDEX idx_scj_session_created(session_id,created_at), CONSTRAINT fk_scj_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS service_config_results (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, job_id VARCHAR(36) NOT NULL, node_id BIGINT NOT NULL, operation VARCHAR(16) NOT NULL, previous_kill_mode VARCHAR(64), new_kill_mode VARCHAR(64), config_method VARCHAR(32), previous_override_exists BOOLEAN, backup_path TEXT, restart_requested BOOLEAN NOT NULL DEFAULT FALSE, restart_status VARCHAR(32), service_state_before VARCHAR(64), service_state_after VARCHAR(64), main_pid_before VARCHAR(64), main_pid_after VARCHAR(64), status VARCHAR(48) NOT NULL, error_code VARCHAR(64), error_message TEXT, started_at DATETIME NOT NULL, finished_at DATETIME NULL, INDEX idx_scr_node(node_id), INDEX idx_scr_job(job_id), CONSTRAINT fk_scr_job FOREIGN KEY(job_id) REFERENCES service_config_jobs(id) ON DELETE CASCADE, CONSTRAINT fk_scr_node FOREIGN KEY(node_id) REFERENCES nodes(id) ON DELETE CASCADE);
